import { POSE_BENCHMARK_RESULTS, POSE_BENCHMARK_RESULTS_IMPORTED_ON } from "@/data/poseBenchmarkResults";
import { ACCEPT_LABEL, NEW_ISSUE_URL, REPO, TITLE_PREFIX } from "@/lib/poseBenchmarkSubmission.mjs";

/**
 * The crowdsourced leaderboard for /tools/pose-benchmark, rendered at build
 * from src/data/poseBenchmarkResults.ts (generated by
 * scripts/import-pose-benchmark-results.mjs from accepted GitHub issues).
 *
 * Every row links the public issue it came from. Rows are grouped by model
 * and delegate and ordered by median latency within a group, because that is
 * the only comparison the numbers support: one run on one device each, so
 * the order says which submitted device was faster on that run, not which
 * hardware is better. Nothing is averaged, filled in or invented, and when
 * there is nothing to show the section says so.
 */

const TEMPLATE_URL = `${NEW_ISSUE_URL}?template=pose-benchmark-result.md`;
const ms = (n: number) => n.toFixed(1);
const linkCls = "font-medium text-brand-600 hover:text-brand-500";

export default function PoseLeaderboard() {
  const groups = new Map<string, { model: string; delegate: string; rows: { sub: (typeof POSE_BENCHMARK_RESULTS)[number]; row: (typeof POSE_BENCHMARK_RESULTS)[number]["rows"][number] }[] }>();
  for (const sub of POSE_BENCHMARK_RESULTS) {
    for (const row of sub.rows) {
      const k = `${row.model}|${row.delegate}`;
      if (!groups.has(k)) groups.set(k, { model: row.model, delegate: row.delegate, rows: [] });
      groups.get(k)!.rows.push({ sub, row });
    }
  }
  for (const g of groups.values()) g.rows.sort((a, b) => a.row.medianMs - b.row.medianMs);
  const ordered = [...groups.values()].sort((a, b) => a.model.localeCompare(b.model) || a.delegate.localeCompare(b.delegate));

  return (
    <section id="leaderboard" data-pose-leaderboard className="mt-14">
      <h2 className="text-2xl font-bold tracking-tight text-[var(--fg)]">Leaderboard: runs readers submitted</h2>
      <p className="mt-4 leading-relaxed text-[var(--muted)]">
        After a run, the page offers a prefilled GitHub issue in this site&rsquo;s public repository (
        <a href={`https://github.com/${REPO}`} className={linkCls} rel="noopener">
          {REPO}
        </a>
        ). A maintainer checks that the numbers came from the page and adds the{" "}
        <code className="font-mono text-sm">{ACCEPT_LABEL}</code> label, and the next build lists the run
        here with a link to its issue. Each row is one run on one device, copied as submitted; the order
        within a model is by median latency on that run and is not a ranking of hardware.
      </p>

      {ordered.length === 0 ? (
        <div data-leaderboard-empty className="mt-6 rounded-2xl border border-dashed border-[var(--border)] bg-[var(--surface)] p-6 text-center">
          <p className="text-lg font-semibold text-[var(--fg)]">No submissions yet. Be the first.</p>
          <p className="mx-auto mt-2 max-w-xl text-sm leading-relaxed text-[var(--muted)]">
            Run the benchmark above, then press <strong className="text-[var(--fg)]">Submit to the leaderboard on GitHub</strong>.
            You can also start from the{" "}
            <a href={TEMPLATE_URL} className={linkCls} rel="noopener">
              issue template
            </a>{" "}
            (titles start with <code className="font-mono text-xs">{TITLE_PREFIX}</code>). This table shows no
            numbers until a real run is accepted: none are filled in for it.
          </p>
        </div>
      ) : (
        <div className="mt-6 space-y-8">
          {ordered.map((g) => (
            <div key={`${g.model}-${g.delegate}`}>
              <h3 className="text-lg font-semibold text-[var(--fg)]">
                {g.model}, {g.delegate} delegate
              </h3>
              <div className="mt-2 overflow-x-auto">
                <table className="w-full min-w-[640px] text-left text-sm">
                  <thead className="text-xs uppercase tracking-wider text-[var(--muted)]">
                    <tr>
                      <th className="py-2 pr-3">Platform</th>
                      <th className="py-2 pr-3">GPU (as reported)</th>
                      <th className="py-2 pr-3 text-right">Median ms</th>
                      <th className="py-2 pr-3 text-right">p95 ms</th>
                      <th className="py-2 pr-3 text-right">Loop fps</th>
                      <th className="py-2 pr-3">Runtime</th>
                      <th className="py-2">Issue</th>
                    </tr>
                  </thead>
                  <tbody>
                    {g.rows.map(({ sub, row }) => (
                      <tr key={`${sub.issue}-${row.model}-${row.delegate}`} className="border-t border-[var(--border)] text-[var(--fg)]">
                        <td className="py-2 pr-3">{sub.device?.platform ?? "not reported"}</td>
                        <td className="py-2 pr-3 text-xs">{sub.device?.gpu ?? "not reported"}</td>
                        <td className="py-2 pr-3 text-right font-mono">{ms(row.medianMs)}</td>
                        <td className="py-2 pr-3 text-right font-mono">{ms(row.p95Ms)}</td>
                        <td className="py-2 pr-3 text-right font-mono">{row.loopFps === null ? "—" : row.loopFps.toFixed(1)}</td>
                        <td className="py-2 pr-3 font-mono text-xs">{sub.runtime}</td>
                        <td className="py-2">
                          <a href={sub.issueUrl} className={linkCls} rel="noopener">
                            #{sub.issue}
                          </a>
                          {sub.submittedOn ? <span className="text-xs text-[var(--muted)]"> · {sub.submittedOn}</span> : null}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          ))}
          <p className="text-xs text-[var(--muted)]">Imported {POSE_BENCHMARK_RESULTS_IMPORTED_ON}.</p>
        </div>
      )}
    </section>
  );
}
